# -*- coding: utf-8 -*-
import time

from taf.playwright.sbts.common.basic_page import PlaywrightBasicPage
from taf.playwright.sbts.common.exceptions import PlaywrightSbtsError


class SbtsLoginPage(PlaywrightBasicPage):
    """Login page object for SBTS Web UI."""

    USERNAME = 'input[name="username"], input[placeholder="Username"], input#username'
    PASSWORD = 'input[name="password"], input[placeholder="Password"], input#password'
    OPTIONS = 'text=Options'
    PORT_INPUT = 'input[id="port"], input[name="port"]'
    SSL_CHECKBOX = 'input[id="SSL"], input[name="useSSL"], input[type="checkbox"]'
    READONLY_CHECKBOX = 'input[id="readOnly"]'
    LOGIN_BUTTON_TEXT = "Login"
    LOGIN_FORM = 'input[name="username"], input[placeholder="Username"], input#username'
    LEGAL_NOTICE_CONFIRM = 'text=Confirm'
    STARTUP_VIEW_CLOSE = 'text=Close'
    SESSION_ERROR = 'text=Session establishment error'
    POST_LOGIN_CANDIDATES = (
        ".user-account-view",
        "text=Configuration",
        "text=Fault Management",
        "text=Software",
        "text=Diagnostics",
        "ot-navigation",
        "ot-main-view",
        '[data-testid="app-shell"]',
    )

    def login(self, url, username, password, port=443, ssl=True, timeout=60, readonly=False):
        self.goto(url, timeout)
        self.fill(self.USERNAME, username, timeout)
        self.fill(self.PASSWORD, password, timeout)
        self._configure_options(port, ssl, readonly, timeout)
        self._click_login(timeout)
        login_result = self._wait_for_login_result(timeout)
        self._close_post_login_modals()
        return login_result

    def _configure_options(self, port, ssl, readonly, timeout):
        self.optional_click(self.OPTIONS, timeout=2)
        if self.is_visible(self.PORT_INPUT, timeout=1):
            self.fill(self.PORT_INPUT, port, timeout)
        self._set_checkbox(self.SSL_CHECKBOX, ssl)
        self._set_checkbox(self.READONLY_CHECKBOX, readonly)

    def _set_checkbox(self, selector, expected):
        if not self.is_visible(selector, timeout=1):
            return
        locator = self.locator(selector).first
        checked = locator.is_checked()
        if bool(checked) != self._to_bool(expected):
            locator.click()

    def _click_login(self, timeout):
        try:
            self.page.get_by_role("button", name=self.LOGIN_BUTTON_TEXT).click(timeout=self._timeout_ms(timeout))
        except Exception:
            self.click("text={}".format(self.LOGIN_BUTTON_TEXT), timeout)

    def _wait_for_login_result(self, timeout):
        deadline = time.time() + min(float(timeout), 20.0)
        while time.time() <= deadline:
            if self.is_visible(self.SESSION_ERROR, timeout=1):
                return self.page.locator("body").inner_text(timeout=self._timeout_ms(timeout))
            if self._is_post_login_page():
                return None
            if not self.is_visible(self.LOGIN_FORM, timeout=1) and not self.is_visible("text=Login", timeout=1):
                return None
            time.sleep(0.3)

        body_preview = self.page.locator("body").inner_text(timeout=self._timeout_ms(3))[:500]
        raise PlaywrightSbtsError(
            "SBTS login did not reach post-login page; still on or near login page. "
            "Check credentials, login options, and selectors. Body preview: {}".format(body_preview)
        )

    def _is_post_login_page(self):
        for selector in self.POST_LOGIN_CANDIDATES:
            if self.is_visible(selector, timeout=1):
                return True
        return False

    @staticmethod
    def _to_bool(value):
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() not in ("false", "0", "no", "off")

    def _close_post_login_modals(self):
        self.optional_click(self.LEGAL_NOTICE_CONFIRM, timeout=3)
        self.optional_click(self.STARTUP_VIEW_CLOSE, timeout=2)


class LogoutPage(PlaywrightBasicPage):
    """Best-effort logout page object for SBTS Web UI."""

    USER_MENU = ".user-account-view"
    LOGOUT = 'text=Logout'

    def logout(self, timeout=10):
        self.optional_click(self.USER_MENU, timeout=2)
        if self.optional_click(self.LOGOUT, timeout=timeout):
            return
        # If the UI logout cannot be found, the caller can still close the browser session.
